package com.tnr.cityguide.review;
import com.tnr.cityguide.auth.FieldValidationException;import com.tnr.cityguide.common.NotFoundException;import com.tnr.cityguide.place.*;import com.tnr.cityguide.user.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class ReviewService {
 private final ReviewRepository reviews;private final ReviewLikeRepository likes;private final PlaceRepository places;private final UserRepository users;private final Clock clock;
 public ReviewService(ReviewRepository r,ReviewLikeRepository l,PlaceRepository p,UserRepository u,Clock c){reviews=r;likes=l;places=p;users=u;clock=c;}
 @Transactional(readOnly=true) public List<ReviewDto> forPlace(String place,UUID me){if(!places.existsById(place))throw new NotFoundException("Place not found.");return reviews.findByPlaceIdOrderByCreatedAtDesc(place).stream().map(r->dto(r,me)).toList();}
 @Transactional public ReviewDto upsert(String place,UUID user,short rating,String text){if(!places.existsById(place))throw new NotFoundException("Place not found.");Map<String,String> errors=new LinkedHashMap<>();if(rating<1||rating>5)errors.put("rating","Please choose a star rating.");if(text==null||text.trim().length()<5)errors.put("text","Please write a short comment (at least 5 characters).");else if(text.trim().length()>600)errors.put("text","Comment must be at most 600 characters.");if(!errors.isEmpty())throw new FieldValidationException(errors.values().iterator().next(),errors);Review r=reviews.findByPlaceIdAndUserId(place,user).orElseGet(Review::new);r.setPlaceId(place);r.setUserId(user);r.setRating(rating);r.setText(text.trim());r.setCreatedAt(clock.instant());reviews.save(r);recalculate(place);return dto(r,user);}
 @Transactional public void delete(UUID id,UUID caller,boolean admin){Review r=reviews.findById(id).orElseThrow(()->new NotFoundException("Review not found."));if(!admin&&!r.getUserId().equals(caller))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only delete your own review.");String place=r.getPlaceId();reviews.delete(r);recalculate(place);}
 @Transactional public LikeState like(UUID id,UUID user,boolean add){Review r=reviews.findById(id).orElseThrow(()->new NotFoundException("Review not found."));ReviewLike.Key key=new ReviewLike.Key(id,user);if(add){if(!likes.existsById(key)){ReviewLike like=new ReviewLike();like.setReviewId(id);like.setUserId(user);likes.save(like);}}else likes.deleteById(key);return new LikeState(likes.countByReviewId(id),likes.existsByReviewIdAndUserId(id,user));}
 @Transactional(readOnly=true) public List<ReviewDto> mine(UUID user){return reviews.findByUserIdOrderByCreatedAtDesc(user).stream().map(r->dto(r,user)).toList();}
 private void recalculate(String id){Place p=places.findById(id).orElseThrow();List<Review> list=reviews.findByPlaceIdOrderByCreatedAtDesc(id);p.setReviewCount(list.size());p.setRatingAvg(list.isEmpty()?p.getBaseRating():list.stream().mapToInt(Review::getRating).average().orElse(p.getBaseRating()));}
 private ReviewDto dto(Review r,UUID me){User a=users.findById(r.getUserId()).orElse(null);Place p=places.findById(r.getPlaceId()).orElse(null);return new ReviewDto(r.getId(),r.getPlaceId(),p==null?null:p.getName(),r.getUserId(),a==null?"":a.getName(),a==null?null:a.getAvatarUrl(),r.getRating(),r.getText(),r.getCreatedAt(),likes.countByReviewId(r.getId()),likes.existsByReviewIdAndUserId(r.getId(),me),r.getUserId().equals(me));}
 public record ReviewDto(UUID id,String placeId,String placeName,UUID userId,String authorName,String authorAvatarUrl,short rating,String text,Instant createdAt,long likeCount,boolean likedByMe,boolean mine){}public record LikeState(long likeCount,boolean likedByMe){}
}
